import React, { useState, useEffect } from 'react';
import { getContacts, addContact, updateContact, deleteContact } from './services/api';

function App() {
  const [contacts, setContacts] = useState([]);
  const [newContact, setNewContact] = useState({ name: '', phone: '', email: '', address: '' });
  const [isEditing, setIsEditing] = useState(false);
  const [editIndex, setEditIndex] = useState(null);

  useEffect(() => {
    fetchContacts();
  }, []);

  const fetchContacts = async () => {
    const response = await getContacts();
    setContacts(response.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (isEditing) {
      await updateContact(editIndex, newContact);
      setIsEditing(false);
    } else {
      await addContact(newContact);
    }
    setNewContact({ name: '', phone: '', email: '', address: '' });
    fetchContacts();
  };

  const handleEdit = (index) => {
    setNewContact(contacts[index]);
    setIsEditing(true);
    setEditIndex(index);
  };

  const handleDelete = async (index) => {
    await deleteContact(index);
    fetchContacts();
  };

  return (
    <div className="App">
      <h1>Contact Management</h1>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Name"
          value={newContact.name}
          onChange={(e) => setNewContact({ ...newContact, name: e.target.value })}
        />
        <input
          type="text"
          placeholder="Phone"
          value={newContact.phone}
          onChange={(e) => setNewContact({ ...newContact, phone: e.target.value })}
        />
        <input
          type="email"
          placeholder="Email"
          value={newContact.email}
          onChange={(e) => setNewContact({ ...newContact, email: e.target.value })}
        />
        <input
          type="text"
          placeholder="Address"
          value={newContact.address}
          onChange={(e) => setNewContact({ ...newContact, address: e.target.value })}
        />
        <button type="submit">{isEditing ? 'Update' : 'Add'} Contact</button>
      </form>

      <h2>Contacts List</h2>
      <ul>
        {contacts.map((contact, index) => (
          <li key={index}>
            {contact.name} - {contact.phone} - {contact.email} - {contact.address}
            <button onClick={() => handleEdit(index)}>Edit</button>
            <button onClick={() => handleDelete(index)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
